"""In-plane complex steps preserve active tangents and all 3D generated bytes."""

import hashlib
import importlib.util
import json
from pathlib import Path

import numpy as np
import pytest

import abaqus_ufl as au
from abaqus_ufl.core.tensor import eye, trace
from abaqus_ufl.generators import uel_gen
from compiled_helpers import build_uel_module, build_umat_module, call_uel, call_umat

ROOT = Path(__file__).resolve().parents[1]


def load_example(name):
    spec = importlib.util.spec_from_file_location('_tangent_' + name, ROOT / 'examples' / name / 'build.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class HistoryMaterial(au.Material):
    props = dict(G=2.0)
    state_vars = dict(a=0.0)

    def stress_PK1(self, F, a_old, dt):
        strain = F - eye(3)
        P = (self.G + a_old) * strain
        work = trace(strain)
        a_new = a_old + dt * work * work
        return P, {'a': a_new}


class UpdatedStressMaterial(au.Material):
    props = dict(G=2.0)
    state_vars = dict(a=0.0, history=0.0)

    def stress_PK1(self, F, a_old, history_old, dt):
        strain = F - eye(3)
        work = trace(strain)
        a_new = a_old + dt * work
        P = (self.G + a_new) * strain
        history_new = history_old + dt * work * work
        return P, {'a': a_new, 'history': history_new}


UpdatedStressMaterial.symmetric_tangent = False


class BranchHistoryMaterial(au.Material):
    props = dict(G=2.0)
    state_vars = dict(a=0.0)
    symmetric_tangent = False

    def stress_PK1(self, F, a_old, dt):
        strain = F - eye(3)
        work = trace(strain)
        a_new = a_old
        if work.real > 0.0:
            a_new = a_old + dt * work
        P = (self.G + a_new) * strain
        return P, {'a': a_new}


def mechanics(material):
    class Problem(au.WeakForm):
        ndim = 2

        def define_fields(self):
            self.u = au.VectorField('u', degree=1)

        def momentum_equation(self, v, F):
            return self.material.stress_PK1(F)

    Problem.material = material
    return Problem()


def source_digests(directory):
    """Whole-file SHA256 values recorded from the unmodified a02ed7c generator."""
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    neo = load_example('neo_hookean_umat').NeoHookean
    digests = {}
    for name, material in [('neo', neo), ('history', HistoryMaterial)]:
        output = directory / ('umat_' + name + '.for')
        au.generate_umat(material(), str(output), verify=False)
        digests[output.name] = hashlib.sha256(output.read_bytes()).hexdigest()
        for formulation in ('standard', 'fbar_mechanics'):
            output = directory / ('hex8_' + name + '_' + formulation + '.for')
            au.generate_uel(mechanics(material), str(output), element='Hex8',
                            formulation=formulation, verify=False)
            digests[output.name] = hashlib.sha256(output.read_bytes()).hexdigest()
    return digests


def test_3d_output_is_byte_identical_to_original_generator(tmp_path):
    expected = json.loads((ROOT / 'tests/data/3d_codegen_sha256.json').read_text())
    assert source_digests(tmp_path) == expected


@pytest.mark.parametrize('example', ['neo_hookean_umat', 'ogden_umat', 'history', 'updated_state'])
def test_plane_strain_umat_matches_nine_perturbations(tmp_path, example):
    if example in ('history', 'updated_state'):
        material = HistoryMaterial if example == 'history' else UpdatedStressMaterial
    else:
        module = load_example(example)
        material = getattr(module, 'NeoHookean', None) or module.OgdenOneTerm
    model = material()
    F = np.array([[1.13, 0.09, 0.0], [0.03, 0.94, 0.0], [0.0, 0.0, 1.0]])
    results = []
    for ndim in (2, 3):
        folder = tmp_path / str(ndim)
        folder.mkdir()
        source = folder / 'umat.for'
        au.generate_umat(model, str(source), ndim=ndim)
        compiled = build_umat_module(source, folder, '_umat_{}_{}'.format(example, ndim))
        from abaqus_ufl.generators.umat_gen import _nstate_per_gp, _state_var_info
        nstate = max(1, _nstate_per_gp(_state_var_info(model)))
        results.append(call_umat(compiled, F, model.props_array,
                                 ntens=4 if ndim == 2 else 6, nstatv=nstate))
        assert results[-1][3] >= 1.0
        assert np.linalg.norm(results[-1][0]) > 1e-3
        assert np.linalg.norm(results[-1][2]) > 1e-3
        if ndim == 2:
            bad = F.copy()
            bad[2, 2] = 1.1
            assert call_umat(compiled, bad, model.props_array, ntens=4, nstatv=nstate)[3] < 1
            assert call_umat(compiled, F, model.props_array, ntens=6, nstatv=nstate)[3] < 1
    assert np.allclose(results[0][0], results[1][0][:4], rtol=0, atol=1e-14)
    for index in (1, 3):  # state, PNEWDT
        assert np.allclose(results[0][index], results[1][index], rtol=0, atol=1e-14)
    # Plane-strain active strain columns: 11, 22, engineering shear 12.
    assert np.allclose(results[0][2][:, [0, 1, 3]], results[1][2][:4, [0, 1, 3]],
                       rtol=2e-14, atol=2e-13)


@pytest.mark.parametrize('kind', ['heat_quad4', 'heat_quad8', 'ogden', 'fbar', 'history',
                                'updated_state', 'fbar_history', 'fbar_updated', 'branch_history'])
def test_2d_uel_matches_full_perturbations(tmp_path, monkeypatch, kind):
    if kind.startswith('heat'):
        example = load_example('scalar_diffusion_uel' if kind == 'heat_quad4' else 'thermo_mechanics_quad8')
        factory = example.HeatDiffusionProblem if kind == 'heat_quad4' else example.ThermoMechanicalQuad8
        topology = 'Quad4' if kind == 'heat_quad4' else 'Quad8'
        formulation = 'standard'
    else:
        example = load_example('ogden_umat')
        material = (HistoryMaterial if kind in ('history', 'fbar_history') else
                    UpdatedStressMaterial if kind in ('updated_state', 'fbar_updated') else
                    BranchHistoryMaterial if kind == 'branch_history' else example.OgdenOneTerm)
        factory = lambda: mechanics(material)
        topology, formulation = 'Quad4', 'fbar_mechanics' if kind.startswith('fbar') else 'standard'
    original_standard = uel_gen._generate_cs_engine
    original_fbar = uel_gen._generate_cs_tangent_dPdF
    results = []
    for full in (False, True):
        folder = tmp_path / str(full)
        folder.mkdir()
        problem = factory()
        source = folder / 'element.for'
        if full:
            monkeypatch.setattr(uel_gen, '_generate_cs_engine',
                                lambda wf, prefix: original_standard(wf, prefix, ndim=3))
            monkeypatch.setattr(uel_gen, '_generate_cs_tangent_dPdF',
                                lambda wf, prefix: original_fbar(wf, prefix, ndim=3))
        au.generate_uel(problem, str(source), element=topology, formulation=formulation)
        compiled = build_uel_module(source, folder, '_uel_{}_{}'.format(kind, int(full)))
        coords = np.array([[0., 0.], [1.2, 0.1], [1.1, 1.0], [-0.1, 0.9]])
        if topology == 'Quad8':
            coords = np.vstack((coords, (coords + np.roll(coords, -1, axis=0)) / 2))
        dpn = 3 if kind.startswith('heat') else 2
        u = np.zeros((len(coords), dpn))
        u[:, :2] = coords @ np.array([[0.1, 0.05], [0.02, -0.03]])
        if dpn == 3:
            u[:, 2] = 0.3 + 0.1*coords[:, 0] + 0.2*coords[:, 1]
        packed = (np.concatenate([u[i] if i < 4 else u[i, :2] for i in range(8)])
                  if topology == 'Quad8' else u.ravel())
        from abaqus_ufl.generators.umat_gen import _nstate_per_gp, _state_var_info
        nstate = max(1, 4*_nstate_per_gp(_state_var_info(problem._mat)))
        # State-bearing calls use nonzero beginning time and nonzero old SVARS.
        results.append(compiled.drive_uel(
            np.full(nstate, 0.2), np.asfortranarray(coords.T), packed, 0.4*packed,
            problem._mat.props_array, np.array([0], np.int32), np.array([0.1, 0.1]),
            0.1, 1.0, np.array([1, 0, 1, 0, 0, 0], np.int32), np.zeros(3), 1, 1, 2, 1, 1.0))
        assert results[-1][3] >= 1.0
        assert np.linalg.norm(results[-1][0]) > 1e-3
        assert np.linalg.norm(results[-1][1]) > 1e-3
    for a, b in zip(*results):
        assert np.allclose(a, b, rtol=2e-14, atol=5e-13)


@pytest.mark.parametrize('ndim', [0, 1, 4, True, 2.0, '2'])
def test_umat_rejects_invalid_dimensions(tmp_path, ndim):
    with pytest.raises(ValueError, match='ndim must be'):
        au.generate_umat(HistoryMaterial(), str(tmp_path / 'bad.for'), ndim=ndim)


def test_state_slicing_retains_stress_dependencies_and_falls_back_for_control_flow():
    import ast
    from abaqus_ufl.generators.umat_gen import _get_source_body, _stress_only_body
    nodes, _ = _get_source_body(UpdatedStressMaterial.stress_PK1)
    sliced, changed = _stress_only_body(nodes)
    assert changed
    code = ast.unparse(ast.Module(body=sliced, type_ignores=[]))
    assert 'a_new =' in code and 'history_new =' not in code
    for source in (
        "if F[0,0].real > 1:\n    h = a_old + 1\nreturn F, {'a': h}",
        "h = self._update(F)\nreturn F, {'a': h}",
        "F[0,0] = 2\nreturn F, {'a': a_old}",
    ):
        body = ast.parse(source).body
        assert _stress_only_body(body) == (body, False)
